import sys
import subprocess

def mailcap_find_match(capaname, mime_type, filename, param_buffer):
    '''
Simuliert die Funktion mailcap.findmatch. 
Konstruiert einen Befehl zum Anzeigen der Datei basierend auf dem mime_type und führt ihn aus.

Diese Implementierung enthält eine Überprüfung, um das Verketten von Befehlen zu verhindern, indem Semikolons blockiert werden.
    '''
    match_command = ''

    try:
        capa = open(capaname, "r")
    except:
        return 1
    try:
        for line in capa.readlines():
            if mime_type in line:
                match_command = line
                break
    except:
        return 1

    try:
        command_list = match_command.split(';')
        command_list_stripped = []
        for command in command_list:
            if not ";" in command:
                command_list_stripped.append(command)

        if len(command_list_stripped) > 1:
            print("Please enter your choice: ")
            for i in range(len(command_list_stripped)):
                print("{}. {}".format(i + 1, command_list_stripped[i]))
            user_input = None
            while True:
                try:
                    user_input = int(input("Your choice: "))
                    if 1 <= user_input <= len(command_list_stripped):
                        user_input -= 1
                        break
                except:
                    continue
            match_command = command_list_stripped[user_input]
        match_command = match_command.replace("<filename>", filename)
    except:
        return 1

    # Führe Befehl aus
    try:
        subprocess.run(match_command.split(' '))
    except:
        return 1
    return 0
