ALLOWED_TAGS = {"p", "hr", "h1", "h2", "h3", "h4", "h5", "h6"}

def sanify(html_text, allowed_tags=ALLOWED_TAGS):
    '''
Sanifica un testo HTML.

Sanificazione non consente di inserire i tag <script> così non sarà possibile sfruttare le vulnerabilità di XSS.
    '''
    # sanificazione
    clean_html_text = ""
    for tag in html_text.split("<"):
        if not tag or tag[0] == "/":
            continue
        clean_html_text += "<" + tag
        if tag.find(">") == -1:
            clean_html_text += "></" + tag[tag.find(" "):]
            continue
        clean_tag = tag[:tag.find(">")]
        attributes = clean_tag[clean_tag.find(" "):].split()
        if len(attributes) == 0:
            clean_html_text += "></" + tag[tag.find(" "):]
            continue
        if attributes[0] == "/>":
            clean_html_text += " />"
            continue
        if tag[0]!= "/":
            clean_html_text += ">"
        for attribute in attributes:
            name = attribute[max(0, attribute.find("=")):attribute.find(" ")]
            if name in allowed_tags:
                clean_name = name[1:] if name.startswith("/") else name
                if attribute.find("=") == -1:
                    clean_html_text += " " + name + " />"
                else:
                    value = attribute[attribute.find('"')+1:attribute.rfind('"')]
                    if name == "style":
                        value = value.replace("'","\\'").replace('"', '\\"')
                    if " " + value + " " in allowed_tags:
                        clean_html_text += " " + attribute
                    else:
                        clean_html_text += " " + clean_name + "=\"" + value + "\""
            else:
                clean_html_text += " " + attribute
    return clean_html_text


