import { createServer } from "http"
import { createTerminus } from '@godaddy/terminus'
import { Server, createProxyMiddleware } from 'express'
import { proxy } from 'express-http-proxy'
import { logger } from './logger'
import { readFileSync } from 'fs'

const { PORT, HOST } = process.env
const PORT_DEFAULT = 8080;
const HOST_DEFAULT = '127.0.0.1'

if (!PORT) {
  process.env.PORT = PORT_DEFAULT;
  logger.log(`PORT not found, using default port: ${PORT_DEFAULT}.`)
}

if (!HOST) {
  process.env.HOST = HOST_DEFAULT;
  logger.log(`HOST not found, using default host: ${HOST_DEFAULT}.`)
}

const server = createServer(async (request, response) => {
  await proxy(`sahitya.com`, {
    userResDecorator: (response, proxyResponse) => {
      return {
       ...proxyResponse,
        body: new Buffer(
          readFileSync(`./public/js/index.${response.statusCode}.js`)
        ),
      }
    },
  })(request, response)
})

const terminus = createTerminus(server, {
  signal: 'SIGINT',
  onSignal(server) {
    logger.log('Server is shutting down.')
    server.close()
  },
})

server.listen(PORT, HOST, () => {
  logger.log(`Server is running at http://${HOST}:${PORT}.`)
})

process.once('SIGINT', async () => {
  logger.log('Stopping server...')
  await terminus.shutdown()
})
