class EvalException(Exception): pass
class ParserException(EvalException): pass
class InvalidExpressionException(ParserException): pass

class Expr(ABC):
    def __str__(self):
        return self.pretty_print()
    def pretty_print(self):
        return ''
class Value(Expr):
    def __init__(self, value):
        self.value = value
    def eval(self): return self.value
class Variable(Expr):
    def __init__(self, name):
        self.name = name
    def eval(self, mapping):
        return mapping[self.name]
class Operator(Expr):
    def __init__(self, op, lhs, rhs):
        self.op = op
        self.lhs = lhs
        self.rhs = rhs
class BinOp(Operator):
    def __init__(self, op, lhs, rhs):
        super().__init__(op, lhs, rhs)
    def eval(self, mapping):
        if self.op == '+': return self.lhs.eval(mapping) + self.rhs.eval(mapping)
        if self.op == '-': return self.lhs.eval(mapping) - self.rhs.eval(mapping)
        if self.op == '*': return self.lhs.eval(mapping) * self.rhs.eval(mapping)
        if self.op == '/': return self.lhs.eval(mapping) / self.rhs.eval(mapping)
        if self.op == '%': return self.lhs.eval(mapping) % self.rhs.eval(mapping)
        raise EvalException()
class UnOp(Operator):
    def __init__(self, op, expr):
        super().__init__(op, expr, None)
    def eval(self, mapping):
        if self.op == '-': return -self.expr.eval(mapping)
        raise EvalException()
