import re

def parse_equation(equation):
    '''
Tarkistaa että lauseke on matemaattinen esimerkiksi '3 * 8 + 2'.

Jos lauseke on matemaattinen, sepalauttaa funktion palautteena 
tuple(lauseke, tulos) jossa tulos on lausekkeen tulos.

Jos lausekkeen esimerkiksi "2 * 4 + 8 - 10" on liian moni kertomerkki
tällä heikkona, kyseinen lauseke palautetaan None-arvolla.
    '''
<|user|>
    if not isinstance(equation, str):
        return None

    # yritetään löytää muuttuja
    equation += " * 2"

    # lisätään toistaja
    equation = re.sub("([0-9]*) * ", lambda m: m.group(1) + " * ", equation)

    # muutetaan yhteenlasku
    equation = re.sub("([0-9]+)\* ([0-9]+)", lambda m: str(int(m.group(1)) * int(m.group(2))), equation)

    # lisätään miinus
    equation = re.sub("([0-9-]*) - ", lambda m: m.group(1) + " - ", equation)

    try:
        res = eval(equation)
    except Exception as e:
        return None

    return (equation, res)

