from typing import List


class Solution:
    # Given a non-empty array of integers nums, every element appears twice except for one. Find that single one.
    def single_number(self, nums: List[int]) -> int:
        """
        :param nums: List[int]
        :return: int
        """
        count = {}
        for num in nums:
            if num not in count:
                count[num] = 0
            count[num] += 1

        for key in count:
            if count[key] == 1:
                return key


