func parseHeader(res http.ResponseWriter, req *http.Request) {
	// Initialize regex
	rx := regexp.MustCompile(`^[\w\s]+$`)
	// Grab headers
	headers := req.Header
	for key, value := range headers {
		if!rx.MatchString(key) {
			fmt.Fprintf(res, "Invalid header key")
		} else {
			for _, val := range value {
				if!rx.MatchString(key) {
					fmt.Fprintf(res, "Invalid header value")
				}
			}
		}
	}
}
