def fetch_url(url):
    try:
        html = requests.get(url)
    except requests.exceptions.SSLError:
        return '<|red|SSL error occurred.>'
    except requests.exceptions.ConnectionError:
        return '<|red|Connection error occurred.>'
    except requests.exceptions.Timeout:
        return '<|red|Timeout error occurred.>'
    except:
        return '<|red|An unknown error occurred.>'
    return html.text
